const chatId = $('Telegram Message').first().json.message.chat.id;
const NL = String.fromCharCode(10);
const out = String($input.first().json.output || '').trim();
const lines = out.split(NL);
let chartTicker = '';
let chartRange = '6mo';
const keep = [];
for (const line of lines) {
  const t = line.trim();
  if (t.toUpperCase().startsWith('CHART:')) {
    const spec = t.slice(6).trim().split('|');
    chartTicker = (spec[0] || '').trim().toUpperCase();
    const r = (spec[1] || '').trim().toLowerCase();
    if (['1mo', '3mo', '6mo', '1y', '2y', '5y'].includes(r)) chartRange = r;
  } else {
    keep.push(line);
  }
}
let body = keep.join(NL).trim();
if (!body) body = 'Here is the chart.';
body = body.split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;');
const pieces = body.split('**');
let html = '';
for (let i = 0; i < pieces.length; i++) {
  if (i > 0) html += (i % 2 === 1 ? '<b>' : '</b>');
  html += pieces[i];
}
if (pieces.length % 2 === 0) html += '</b>';
if (html.length > 3900) html = html.slice(0, 3900) + '...';
const symbolOk = chartTicker.length > 0 && chartTicker.length <= 15 && /^[A-Z0-9.^=-]+$/.test(chartTicker);
return [{ json: { chatId, text: html, hasChart: symbolOk, chartTicker, chartRange } }];

const p = $('Prepare Reply').first().json;
const root = $input.first().json;
const res = root.chart && root.chart.result && root.chart.result[0];
if (!res || !res.timestamp) { return []; }
const meta = res.meta || {};
const q = (res.indicators && res.indicators.quote && res.indicators.quote[0]) || {};
const bars = [];
for (let i = 0; i < res.timestamp.length; i++) {
  if (q.close[i] === null || q.close[i] === undefined || q.open[i] === null || q.high[i] === null || q.low[i] === null) continue;
  bars.push({ t: res.timestamp[i] * 1000, o: q.open[i], h: q.high[i], l: q.low[i], c: q.close[i], v: (q.volume && q.volume[i]) || 0 });
}
if (bars.length < 5) { return []; }
const r2 = (v) => Math.round(v * 100) / 100;
const allC = bars.map(x => x.c);
const smaAt = (k, pos) => {
  if (pos + 1 < k) return null;
  let s = 0;
  for (let j = pos - k + 1; j <= pos; j++) s += allC[j];
  return r2(s / k);
};
const step = Math.max(1, Math.ceil(bars.length / 110));
const candles = [];
const vols = [];
const ma20 = [];
const ma50 = [];
for (let s = 0; s < bars.length; s += step) {
  const e = Math.min(bars.length, s + step);
  let hi = -Infinity, lo = Infinity, vs = 0;
  for (let j = s; j < e; j++) { if (bars[j].h > hi) hi = bars[j].h; if (bars[j].l < lo) lo = bars[j].l; vs += bars[j].v; }
  const x = bars[e - 1].t;
  const o = bars[s].o, c = bars[e - 1].c;
  candles.push({ x: x, o: r2(o), h: r2(hi), l: r2(lo), c: r2(c) });
  vols.push({ x: x, y: Math.round(vs / (e - s)), up: c >= o });
  const a = smaAt(20, e - 1), b = smaAt(50, e - 1);
  if (a !== null) ma20.push({ x: x, y: a });
  if (b !== null) ma50.push({ x: x, y: b });
}
const firstC = bars[0].c;
const lastC = bars[bars.length - 1].c;
const chg = (lastC / firstC - 1) * 100;
const up = lastC >= firstC;
const UP = '#00e676', DOWN = '#ff5252';
let hiAll = -Infinity, loAll = Infinity;
for (const k of candles) { if (k.h > hiAll) hiAll = k.h; if (k.l < loAll) loAll = k.l; }
const pad = (hiAll - loAll) || hiAll * 0.05 || 1;
const yMinRaw = loAll - pad * 0.4;
const yMaxRaw = hiAll + pad * 0.08;
const yMin = pad >= 10 ? Math.floor(yMinRaw / 5) * 5 : r2(yMinRaw);
const yMax = pad >= 10 ? Math.ceil(yMaxRaw / 5) * 5 : r2(yMaxRaw);
const maxVol = Math.max.apply(null, vols.map(v => v.y)) || 1;
const name = meta.longName || meta.shortName || p.chartTicker;
const sym = meta.symbol || p.chartTicker;
const datasets = [];
datasets.push({ type: 'candlestick', label: 'Price', data: candles, yAxisID: 'y', color: { up: UP, down: DOWN, unchanged: '#9e9e9e' }, borderColor: { up: UP, down: DOWN, unchanged: '#9e9e9e' }, borderWidth: 1.4 });
if (ma20.length > 3) datasets.push({ type: 'line', label: '20-day avg', data: ma20, yAxisID: 'y', borderColor: '#ffd54f', borderWidth: 1.5, pointRadius: 0, tension: 0.2, fill: false });
if (ma50.length > 3) datasets.push({ type: 'line', label: '50-day avg', data: ma50, yAxisID: 'y', borderColor: '#4fc3f7', borderWidth: 1.5, pointRadius: 0, tension: 0.2, fill: false });
if (maxVol > 1) datasets.push({ type: 'bar', label: 'Volume', data: vols.map(v => ({ x: v.x, y: v.y })), yAxisID: 'yv', backgroundColor: vols.map(v => v.up ? 'rgba(0,230,118,0.45)' : 'rgba(255,82,82,0.45)'), borderWidth: 0, barPercentage: 0.9, categoryPercentage: 1.0 });
const lastColor = up ? UP : DOWN;
const chartConfig = {
  type: 'candlestick',
  data: { datasets: datasets },
  options: {
    animation: false,
    layout: { padding: { left: 12, right: 8, top: 6, bottom: 8 } },
    plugins: {
      title: { display: true, text: name + ' (' + sym + ')   ' + lastC.toFixed(2) + ' ' + (meta.currency || '') + '   ' + (chg >= 0 ? '+' : '') + chg.toFixed(1) + '% / ' + p.chartRange, color: '#ffffff', font: { size: 20, weight: 'bold' }, padding: { top: 6, bottom: 12 } },
      legend: { display: true, position: 'top', labels: { color: '#bdbdbd', boxWidth: 14, font: { size: 12 } } },
      annotation: { annotations: { last: { type: 'line', scaleID: 'y', yScaleID: 'y', value: r2(lastC), yMin: r2(lastC), yMax: r2(lastC), borderColor: lastColor, borderWidth: 1, borderDash: [4, 4], label: { enabled: true, display: true, content: lastC.toFixed(2), position: 'end', backgroundColor: lastColor, color: '#000000', font: { size: 12, weight: 'bold' }, padding: 4 } } } }
    },
    scales: {
      x: { type: 'timeseries', offset: true, grid: { color: 'rgba(255,255,255,0.06)' }, ticks: { color: '#9e9e9e', maxTicksLimit: 8, maxRotation: 0, source: 'auto' }, time: { unit: step > 3 ? 'month' : (bars.length > 120 ? 'month' : 'week'), displayFormats: { week: 'MMM d', month: 'MMM yy' } } },
      y: { position: 'right', min: yMin, max: yMax, grid: { color: 'rgba(255,255,255,0.12)', borderDash: [3, 4] }, ticks: { color: '#e0e0e0', font: { size: 12 }, maxTicksLimit: 9 } },
      yv: { position: 'left', min: 0, max: Math.round(maxVol * 4.2), display: false, grid: { display: false } }
    }
  }
};
const esc = (v) => String(v).split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;');
const caption = esc(name) + ' (' + esc(sym) + '): ' + lastC.toFixed(2) + ' ' + esc(meta.currency || '') + ', ' + (chg >= 0 ? '+' : '') + chg.toFixed(1) + '% over ' + p.chartRange;
return [{ json: { chatId: p.chatId, chartConfig: chartConfig, caption: caption } }];
